-- SQL standard oriented schema (PostgreSQL compatible).
-- All IDs are UUIDv7 stored as VARCHAR(36) and generated by the application.
-- All tables use soft-delete via deleted_at.

CREATE EXTENSION IF NOT EXISTS postgis;

-- =========================
-- Identity and Access
-- =========================

CREATE TABLE IF NOT EXISTS roles (
  id VARCHAR(36) PRIMARY KEY,
  role_key VARCHAR(50) NOT NULL UNIQUE,
  name VARCHAR(100) NOT NULL,
  description TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP
);

CREATE TABLE IF NOT EXISTS users (
  id VARCHAR(36) PRIMARY KEY,
  email VARCHAR(320) NOT NULL UNIQUE,
  password_hash VARCHAR(255) NOT NULL,
  password_hash_version VARCHAR(50),
  status VARCHAR(30) NOT NULL DEFAULT 'active',
  email_confirmed_at TIMESTAMP,
  locale VARCHAR(10) NOT NULL DEFAULT 'pt-BR',
  time_zone VARCHAR(50),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  CHECK (status IN ('active', 'pending', 'suspended'))
);

CREATE TABLE IF NOT EXISTS email_confirmations (
  id VARCHAR(36) PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL,
  token_hash VARCHAR(128) NOT NULL,
  sent_at TIMESTAMP,
  expires_at TIMESTAMP NOT NULL,
  confirmed_at TIMESTAMP,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS user_roles (
  id VARCHAR(36) PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL,
  role_id VARCHAR(36) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  UNIQUE (user_id, role_id),
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (role_id) REFERENCES roles(id)
);

CREATE TABLE IF NOT EXISTS user_profiles (
  id VARCHAR(36) PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL UNIQUE,
  display_name VARCHAR(200),
  document_type VARCHAR(30),
  document_number VARCHAR(50),
  birth_date DATE,
  phone VARCHAR(50),
  country_code CHAR(2),
  address_line1 VARCHAR(200),
  address_line2 VARCHAR(200),
  address_city VARCHAR(120),
  address_state VARCHAR(120),
  address_postal_code VARCHAR(30),
  address_country CHAR(2),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS organizations (
  id VARCHAR(36) PRIMARY KEY,
  legal_name VARCHAR(200) NOT NULL,
  trade_name VARCHAR(200),
  document_type VARCHAR(30),
  document_number VARCHAR(50),
  email VARCHAR(320),
  phone VARCHAR(50),
  country_code CHAR(2),
  address_line1 VARCHAR(200),
  address_line2 VARCHAR(200),
  address_city VARCHAR(120),
  address_state VARCHAR(120),
  address_postal_code VARCHAR(30),
  address_country CHAR(2),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP
);

CREATE TABLE IF NOT EXISTS organization_members (
  id VARCHAR(36) PRIMARY KEY,
  organization_id VARCHAR(36) NOT NULL,
  user_id VARCHAR(36) NOT NULL,
  role_in_org VARCHAR(50) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  UNIQUE (organization_id, user_id),
  FOREIGN KEY (organization_id) REFERENCES organizations(id),
  FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS producer_profiles (
  id VARCHAR(36) PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL UNIQUE,
  farm_name VARCHAR(200),
  farm_size_ha DECIMAL(12, 2),
  notes TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);

-- =========================
-- Files and Evidence
-- =========================

CREATE TABLE IF NOT EXISTS files (
  id VARCHAR(36) PRIMARY KEY,
  owner_user_id VARCHAR(36),
  file_type VARCHAR(50),
  file_name VARCHAR(255),
  mime_type VARCHAR(100),
  storage_url TEXT NOT NULL,
  checksum VARCHAR(128),
  size_bytes DECIMAL(20, 0),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (owner_user_id) REFERENCES users(id)
);

-- =========================
-- Areas (Projects)
-- =========================

CREATE TABLE IF NOT EXISTS areas (
  id VARCHAR(36) PRIMARY KEY,
  owner_user_id VARCHAR(36) NOT NULL,
  name VARCHAR(200) NOT NULL,
  description TEXT,
  location GEOGRAPHY(POINT, 4326) NOT NULL,
  biome VARCHAR(100),
  state VARCHAR(50),
  city VARCHAR(100),
  country_code CHAR(2),
  status VARCHAR(30) NOT NULL DEFAULT 'draft',
  audit_status VARCHAR(30),
  audit_notes TEXT,
  audited_by_user_id VARCHAR(36),
  audited_at TIMESTAMP,
  total_capacity_t_co2e DECIMAL(18, 6),
  committed_t_co2e DECIMAL(18, 6) DEFAULT 0,
  t_co2e_per_tree_per_year DECIMAL(10, 6),
  price_per_tree DECIMAL(10, 2),
  default_horizon_years INT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP
);

ALTER TABLE areas ADD CONSTRAINT check_status
  CHECK (status IN ('draft', 'pending_audit', 'approved', 'active', 'rejected', 'suspended'));

ALTER TABLE areas ADD CONSTRAINT check_audit_status
  CHECK (audit_status IS NULL OR audit_status IN ('pending', 'approved', 'rejected'));

ALTER TABLE areas ADD CONSTRAINT check_capacity
  CHECK (total_capacity_t_co2e IS NULL OR total_capacity_t_co2e >= 0);

ALTER TABLE areas ADD CONSTRAINT check_committed
  CHECK (committed_t_co2e >= 0);

ALTER TABLE areas ADD CONSTRAINT areas_owner_user_id_fkey
  FOREIGN KEY (owner_user_id) REFERENCES users(id);

ALTER TABLE areas ADD CONSTRAINT areas_audited_by_user_id_fkey
  FOREIGN KEY (audited_by_user_id) REFERENCES users(id);

CREATE TABLE IF NOT EXISTS area_status_history (
  id VARCHAR(36) PRIMARY KEY,
  area_id VARCHAR(36) NOT NULL,
  from_status VARCHAR(30),
  to_status VARCHAR(30) NOT NULL,
  changed_by_user_id VARCHAR(36) NOT NULL,
  reason TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (area_id) REFERENCES areas(id),
  FOREIGN KEY (changed_by_user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS area_documents (
  id VARCHAR(36) PRIMARY KEY,
  area_id VARCHAR(36) NOT NULL,
  file_id VARCHAR(36) NOT NULL,
  doc_type VARCHAR(50) NOT NULL,
  issue_date DATE,
  expiration_date DATE,
  verified_by_user_id VARCHAR(36),
  verified_at TIMESTAMP,
  notes TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (area_id) REFERENCES areas(id),
  FOREIGN KEY (file_id) REFERENCES files(id),
  FOREIGN KEY (verified_by_user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS area_evidence (
  id VARCHAR(36) PRIMARY KEY,
  area_id VARCHAR(36) NOT NULL,
  file_id VARCHAR(36) NOT NULL,
  evidence_type VARCHAR(50),
  captured_at TIMESTAMP,
  location GEOGRAPHY(POINT, 4326),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (area_id) REFERENCES areas(id),
  FOREIGN KEY (file_id) REFERENCES files(id)
);

CREATE TABLE IF NOT EXISTS area_reviews (
  id VARCHAR(36) PRIMARY KEY,
  area_id VARCHAR(36) NOT NULL,
  reviewer_user_id VARCHAR(36) NOT NULL,
  status VARCHAR(30) NOT NULL,
  notes TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  CHECK (status IN ('in_review', 'needs_info', 'approved', 'rejected')),
  FOREIGN KEY (area_id) REFERENCES areas(id),
  FOREIGN KEY (reviewer_user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS area_criteria (
  id VARCHAR(36) PRIMARY KEY,
  area_id VARCHAR(36) NOT NULL,
  criterion_key VARCHAR(100) NOT NULL,
  criterion_label VARCHAR(200) NOT NULL,
  met BOOLEAN NOT NULL DEFAULT FALSE,
  notes TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (area_id) REFERENCES areas(id)
);

-- =========================
-- Emission Factors and Calculations
-- =========================

CREATE TABLE IF NOT EXISTS emission_factors (
  id VARCHAR(36) PRIMARY KEY,
  activity_type VARCHAR(100) NOT NULL,
  unit VARCHAR(30) NOT NULL,
  factor_value DECIMAL(18, 6) NOT NULL,
  factor_unit VARCHAR(30) NOT NULL,
  source TEXT,
  valid_from DATE,
  valid_to DATE,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP
);

CREATE TABLE IF NOT EXISTS footprint_calculations (
  id VARCHAR(36) PRIMARY KEY,
  user_id VARCHAR(36) NOT NULL,
  total_co2_kg DECIMAL(18, 6) NOT NULL,
  unit VARCHAR(10) NOT NULL DEFAULT 'kg',
  calculation_method VARCHAR(100),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE TABLE IF NOT EXISTS footprint_items (
  id VARCHAR(36) PRIMARY KEY,
  calculation_id VARCHAR(36) NOT NULL,
  activity_type VARCHAR(100) NOT NULL,
  quantity DECIMAL(18, 6) NOT NULL,
  unit VARCHAR(30) NOT NULL,
  co2_kg DECIMAL(18, 6) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (calculation_id) REFERENCES footprint_calculations(id)
);

-- =========================
-- Carbon Units and Compensations
-- =========================

CREATE TABLE IF NOT EXISTS carbon_units (
  id VARCHAR(36) PRIMARY KEY,
  area_id VARCHAR(36) NOT NULL,
  unit_type VARCHAR(30) NOT NULL,
  estimated_co2_kg DECIMAL(18, 6) NOT NULL,
  status VARCHAR(30) NOT NULL DEFAULT 'available',
  reserved_at TIMESTAMP,
  retired_at TIMESTAMP,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  CHECK (status IN ('available', 'reserved', 'retired')),
  FOREIGN KEY (area_id) REFERENCES areas(id)
);

CREATE TABLE IF NOT EXISTS compensations (
  id VARCHAR(36) PRIMARY KEY,
  supporter_user_id VARCHAR(36) NOT NULL,
  area_id VARCHAR(36) NOT NULL,
  calculation_id VARCHAR(36),
  total_co2_kg DECIMAL(18, 6) NOT NULL,
  total_amount DECIMAL(18, 2) NOT NULL,
  currency CHAR(3) NOT NULL,
  status VARCHAR(30) NOT NULL DEFAULT 'pending',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  CHECK (status IN ('pending', 'paid', 'canceled', 'refunded')),
  FOREIGN KEY (supporter_user_id) REFERENCES users(id),
  FOREIGN KEY (area_id) REFERENCES areas(id),
  FOREIGN KEY (calculation_id) REFERENCES footprint_calculations(id)
);

CREATE TABLE IF NOT EXISTS compensation_units (
  id VARCHAR(36) PRIMARY KEY,
  compensation_id VARCHAR(36) NOT NULL,
  carbon_unit_id VARCHAR(36) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  UNIQUE (compensation_id, carbon_unit_id),
  FOREIGN KEY (compensation_id) REFERENCES compensations(id),
  FOREIGN KEY (carbon_unit_id) REFERENCES carbon_units(id)
);

CREATE TABLE IF NOT EXISTS payments (
  id VARCHAR(36) PRIMARY KEY,
  compensation_id VARCHAR(36) NOT NULL,
  provider VARCHAR(50) NOT NULL,
  provider_reference VARCHAR(100),
  amount DECIMAL(18, 2) NOT NULL,
  currency CHAR(3) NOT NULL,
  status VARCHAR(30) NOT NULL,
  paid_at TIMESTAMP,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  CHECK (status IN ('pending', 'paid', 'failed', 'refunded')),
  FOREIGN KEY (compensation_id) REFERENCES compensations(id)
);

CREATE TABLE IF NOT EXISTS certificates (
  id VARCHAR(36) PRIMARY KEY,
  compensation_id VARCHAR(36) NOT NULL,
  certificate_number VARCHAR(100) NOT NULL,
  file_id VARCHAR(36),
  issued_at TIMESTAMP,
  status VARCHAR(30) NOT NULL DEFAULT 'issued',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  CHECK (status IN ('issued', 'revoked')),
  FOREIGN KEY (compensation_id) REFERENCES compensations(id),
  FOREIGN KEY (file_id) REFERENCES files(id)
);

-- =========================
-- Localization and Audit
-- =========================

CREATE TABLE IF NOT EXISTS localized_texts (
  id VARCHAR(36) PRIMARY KEY,
  entity_type VARCHAR(100) NOT NULL,
  entity_id VARCHAR(36) NOT NULL,
  field_key VARCHAR(100) NOT NULL,
  locale VARCHAR(10) NOT NULL,
  text_value TEXT NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  UNIQUE (entity_type, entity_id, field_key, locale)
);

CREATE TABLE IF NOT EXISTS audit_log (
  id VARCHAR(36) PRIMARY KEY,
  actor_user_id VARCHAR(36),
  action VARCHAR(100) NOT NULL,
  entity_type VARCHAR(100) NOT NULL,
  entity_id VARCHAR(36),
  reason TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP,
  FOREIGN KEY (actor_user_id) REFERENCES users(id)
);

-- =========================
-- Indexes (FK and lookup)
-- =========================

CREATE INDEX IF NOT EXISTS idx_user_roles_user_id ON user_roles(user_id);
CREATE INDEX IF NOT EXISTS idx_user_roles_role_id ON user_roles(role_id);
CREATE INDEX IF NOT EXISTS idx_user_profiles_user_id ON user_profiles(user_id);
CREATE INDEX IF NOT EXISTS idx_email_confirmations_user_id ON email_confirmations(user_id);
CREATE INDEX IF NOT EXISTS idx_email_confirmations_token_hash ON email_confirmations(token_hash);
CREATE INDEX IF NOT EXISTS idx_organization_members_org_id ON organization_members(organization_id);
CREATE INDEX IF NOT EXISTS idx_organization_members_user_id ON organization_members(user_id);
CREATE INDEX IF NOT EXISTS idx_producer_profiles_user_id ON producer_profiles(user_id);
CREATE INDEX IF NOT EXISTS idx_files_owner_user_id ON files(owner_user_id);
CREATE INDEX IF NOT EXISTS idx_areas_owner ON areas(owner_user_id);
CREATE INDEX IF NOT EXISTS idx_areas_status ON areas(status);
CREATE INDEX IF NOT EXISTS idx_areas_biome ON areas(biome);
CREATE INDEX IF NOT EXISTS idx_areas_location ON areas USING GIST (location);
CREATE INDEX IF NOT EXISTS idx_areas_deleted ON areas(deleted_at);
CREATE INDEX IF NOT EXISTS idx_areas_audit_status ON areas(audit_status);
CREATE INDEX IF NOT EXISTS idx_area_criteria_area_id ON area_criteria(area_id);
CREATE INDEX IF NOT EXISTS idx_area_criteria_deleted ON area_criteria(deleted_at);
CREATE INDEX IF NOT EXISTS idx_area_status_history_area_id ON area_status_history(area_id);
CREATE INDEX IF NOT EXISTS idx_area_documents_area_id ON area_documents(area_id);
CREATE INDEX IF NOT EXISTS idx_area_documents_file_id ON area_documents(file_id);
CREATE INDEX IF NOT EXISTS idx_area_evidence_area_id ON area_evidence(area_id);
CREATE INDEX IF NOT EXISTS idx_area_evidence_file_id ON area_evidence(file_id);
CREATE INDEX IF NOT EXISTS idx_area_reviews_area_id ON area_reviews(area_id);
CREATE INDEX IF NOT EXISTS idx_area_reviews_reviewer_id ON area_reviews(reviewer_user_id);
CREATE INDEX IF NOT EXISTS idx_emission_factors_activity ON emission_factors(activity_type);
CREATE INDEX IF NOT EXISTS idx_footprint_calculations_user_id ON footprint_calculations(user_id);
CREATE INDEX IF NOT EXISTS idx_footprint_items_calc_id ON footprint_items(calculation_id);
CREATE INDEX IF NOT EXISTS idx_carbon_units_area_id ON carbon_units(area_id);
CREATE INDEX IF NOT EXISTS idx_carbon_units_status ON carbon_units(status);
CREATE INDEX IF NOT EXISTS idx_compensations_supporter ON compensations(supporter_user_id);
CREATE INDEX IF NOT EXISTS idx_compensations_area_id ON compensations(area_id);
CREATE INDEX IF NOT EXISTS idx_compensation_units_comp_id ON compensation_units(compensation_id);
CREATE INDEX IF NOT EXISTS idx_compensation_units_unit_id ON compensation_units(carbon_unit_id);
CREATE INDEX IF NOT EXISTS idx_payments_comp_id ON payments(compensation_id);
CREATE INDEX IF NOT EXISTS idx_certificates_comp_id ON certificates(compensation_id);
CREATE INDEX IF NOT EXISTS idx_localized_texts_entity ON localized_texts(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS idx_audit_log_actor ON audit_log(actor_user_id);

-- =========================
-- Views
-- =========================

DROP VIEW IF EXISTS available_areas;

CREATE OR REPLACE VIEW available_areas AS
SELECT
  a.*,
  (COALESCE(a.total_capacity_t_co2e, 0) - COALESCE(a.committed_t_co2e, 0)) AS available_t_co2e
FROM areas a
WHERE a.status = 'active'
  AND a.deleted_at IS NULL
  AND (COALESCE(a.total_capacity_t_co2e, 0) - COALESCE(a.committed_t_co2e, 0)) > 0;

-- =========================
-- Legacy FK updates
-- =========================

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables
             WHERE table_name = 'compensation_projection') THEN
    ALTER TABLE compensation_projection DROP CONSTRAINT IF EXISTS compensation_projection_area_id_fkey;
    ALTER TABLE compensation_projection ADD CONSTRAINT compensation_projection_area_id_fkey
      FOREIGN KEY (area_id) REFERENCES areas(id);
  END IF;
END $$;
